func TestOcrTextIsTaggedAsOcrOnThePagesThatWereRead(emonT *testing.T) {
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	model.PageNew(pages, 1, 61200, 79200, 0, model.PkVector())
	model.PageNew(pages, 2, 61200, 79200, 0, model.PkVector())
	var p1 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var t1 int32 = model.NodeNew(nodes, model.NkText(), p1)
	var p2 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var t2 int32 = model.NodeNew(nodes, model.NkText(), p2)
	model.NodeAddRegion(nodes, regions, p1, 1, 0, 0, 100, 100)
	model.NodeAddRegion(nodes, regions, p2, 2, 0, 0, 100, 100)
	model.NodeAddSrc(nodes, p1, model.SrText())
	model.NodeAddSrc(nodes, p1, model.SrInfer())
	model.NodeAddSrc(nodes, t1, model.SrText())
	model.NodeSetConf(nodes, t1, 1000)
	model.NodeAddSrc(nodes, p2, model.SrText())
	model.NodeAddSrc(nodes, t2, model.SrText())
	model.NodeSetConf(nodes, t2, 1000)
	port.CellsPush(mask, 2)
	port.CellsPush(mask, 0)
	port.AssertEq(emonT, scan.ScTag(nodes, attrs, text, regions, pages, mask, 2), 1, "something was tagged")
	port.AssertEq(emonT, model.NodeSrc(nodes, p1), model.SrOcr()+model.SrInfer(), "page 1's paragraph: `ocr` for `text`, `infer` kept")
	port.AssertEq(emonT, model.NodeSrc(nodes, t1), model.SrOcr(), "its text")
	port.AssertEq(emonT, model.NodeConf(nodes, t1), 500, "an engine's word is not a glyph's own text: uncalibrated 500")
	port.AssertEq(emonT, model.NodeFlags(nodes, p1), model.FlOcrOnly(), "the block says it is OCR only")
	port.AssertEq(emonT, model.NodeFlags(nodes, t1), 0, "an inline is not flagged")
	port.AssertEq(emonT, model.NodeSrc(nodes, p2), model.SrText(), "page 2 was not OCR'd: untouched")
	port.AssertEq(emonT, model.NodeConf(nodes, t2), 1000, "and so is its confidence")
	port.AssertEq(emonT, model.PageKind(pages, 0), model.PkScanned(), "a PDF page that was read is `scanned`")
	port.AssertEq(emonT, model.PageKind(pages, 1), model.PkVector(), "the other is not")
	var a int32 = model.NodeAttr(nodes, attrs, 0, model.FkOcr())
	port.AssertThat(emonT, a >= 0, "settings.ocr is written")
	port.AssertEq(emonT, model.AttrLen(attrs, a), 6, "`always`")
}

func TestAPageInAScriptTheEngineCannotReadIsFlaggedAndHeldAtALowConfidence(emonT *testing.T) {
	// D564 (P12.3 I-13): the page unit adds `sc-mask-unread` to the page's mask cell; the blocks of the page say the engine could not read it
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	model.PageNew(pages, 1, 61200, 79200, 0, model.PkVector())
	model.PageNew(pages, 2, 61200, 79200, 0, model.PkVector())
	model.PageNew(pages, 3, 61200, 79200, 0, model.PkVector())
	var p1 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var t1 int32 = model.NodeNew(nodes, model.NkText(), p1)
	var p2 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var p3 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var p4 int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	model.NodeAddRegion(nodes, regions, p1, 1, 0, 0, 100, 100)
	model.NodeAddRegion(nodes, regions, p2, 2, 0, 0, 100, 100)
	model.NodeAddRegion(nodes, regions, p3, 3, 0, 0, 100, 100)
	model.NodeAddRegion(nodes, regions, p4, 3, 200, 200, 300, 300)
	model.NodeAddSrc(nodes, p1, model.SrText())
	model.NodeSetConf(nodes, p1, 900)
	model.NodeAddSrc(nodes, t1, model.SrText())
	model.NodeSetConf(nodes, t1, 1000)
	model.NodeAddSrc(nodes, p2, model.SrText())
	model.NodeSetConf(nodes, p2, 900)
	// page 3 is born digital, OCR'd, and fusion gave a block to OCR (`ocr` and `text`) and left one to the text layer
	model.NodeAddSrc(nodes, p3, model.SrText())
	model.NodeAddSrc(nodes, p3, model.SrOcr())
	model.NodeSetConf(nodes, p3, 900)
	model.NodeAddSrc(nodes, p4, model.SrText())
	model.NodeSetConf(nodes, p4, 900)
	port.CellsPush(mask, 1+scan.ScMaskUnread())
	port.CellsPush(mask, 1)
	port.CellsPush(mask, scan.ScMaskUnread())
	port.AssertEq(emonT, scan.ScTag(nodes, attrs, text, regions, pages, mask, 2), 1, "something was tagged")
	port.AssertEq(emonT, model.NodeFlags(nodes, p1), model.FlOcrOnly(), "the scan tags what it always tagged")
	port.AssertEq(emonT, scan.ScTagUnread(nodes, regions, mask), 3, "the block and the text of page 1, the block of page 3")
	port.AssertEq(emonT, model.NodeFlags(nodes, p1), model.FlOcrOnly()+(model.FlLowConf()+model.FlScriptUnread()), "the block: OCR only, low confidence, script unread")
	port.AssertEq(emonT, model.NodeConf(nodes, p1), scan.ScUnreadConf(), "its confidence is held at the unread ceiling")
	port.AssertEq(emonT, model.NodeConf(nodes, t1), scan.ScUnreadConf(), "so is its text's")
	port.AssertEq(emonT, model.NodeFlags(nodes, t1), 0, "an inline is not flagged")
	port.AssertEq(emonT, model.NodeSrc(nodes, p1), model.SrOcr(), "its text is still OCR's: it is kept, not dropped")
	port.AssertEq(emonT, model.NodeFlags(nodes, p2), model.FlOcrOnly(), "the other page was read by a model that reads it: OCR only, nothing more")
	port.AssertEq(emonT, model.NodeConf(nodes, p2), 900, "and its confidence is its own")
	port.AssertEq(emonT, model.NodeFlags(nodes, p3), model.FlLowConf()+model.FlScriptUnread(), "a born-digital block OCR won on an unread page: flagged, not `ocr-only`")
	port.AssertEq(emonT, model.NodeConf(nodes, p3), scan.ScUnreadConf(), "and held low")
	port.AssertEq(emonT, model.NodeFlags(nodes, p4), 0, "a block of the same page that stayed the text layer's is not touched")
	port.AssertEq(emonT, model.NodeConf(nodes, p4), 900, "nor its confidence")
	port.AssertEq(emonT, model.PageKind(pages, 0), model.PkVector(), "an image page's kind is not changed by the flag")
}

